'use strict';

// MODULES //

var addon = require( './../src/addon.node' );


// MAIN //

/**
* Compute the Huber loss.
*
* @private
* @param {number} d - threshold
* @param {number} y - true target value
* @param {number} p - predicted value
* @returns {number} Huber loss
*
* @example
* var v = huber( 5.0, 10.2, 0.782 );
* // returns 34.59
*
* @example
* var v = huber( 2.0, 8.0, 0.202 );
* // returns 13.596
*
* @example
* var v = huber( 1.0, 23.2, -0.999 );
* // returns 23.699
*
* @example
* var v = huber( 11.0, -12.2, 0.234 );
* // returns 76.274
*
* @example
* var v = huber( 2.0, -21.0, 0.2 );
* // returns 40.4
*
* @example
* var v = huber( 9.0, 4.0, -0.9 );
* // returns 12.005
*/
function huber( d, y, p ) {
	return addon( d, y, p );
}


// EXPORTS //

module.exports = huber;
